CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, price INTEGER NOT NULL, description TEXT DEFAULT '', images TEXT DEFAULT '[]', video TEXT DEFAULT '', category TEXT DEFAULT '', visible INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT UNIQUE NOT NULL, product_id INTEGER, product_code TEXT NOT NULL, product_name TEXT NOT NULL, quantity INTEGER NOT NULL, amount INTEGER NOT NULL, customer_name TEXT NOT NULL, whatsapp TEXT NOT NULL, house_no TEXT DEFAULT '', address TEXT DEFAULT '', pin_code TEXT DEFAULT '', custom_status TEXT DEFAULT 'ऑर्डर प्राप्त हो गया है', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS order_updates (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, update_text TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(order_id));
